      const labels = ['Caliente M','Caliente G','Frío M','Frío G','Frappé M','Frappé G'];
      const thead = `<thead><tr><th rowspan="2">Producto y contenido</th><th colspan="2">Caliente</th><th colspan="2">Frío</th><th colspan="2">Frappé</th></tr><tr><th>M</th><th>G</th><th>M</th><th>G</th><th>M</th><th>G</th></tr></thead>`;
      const rows = items.map(([name, description, prices]) => `<tr><td><span class="product-name">${name}</span><span class="product-desc">${description}</span></td>${prices.map((price, i) => `<td data-label="${labels[i]}"><span class="${price == null ? 'unlisted' : 'price'}">${price == null ? '—' : '$' + price}</span></td>`).join('')}</tr>`).join('');
      document.getElementById(targetId).innerHTML = `<div class="table-shell"><table class="menu-table">${thead}<tbody>${rows}</tbody></table></div>`;
    }
    renderMenu('coffee-menu', coffeeItems);
    renderMenu('drinks-menu', drinkItems);
    document.querySelectorAll('.filter-button').forEach(button => button.addEventListener('click', () => {
      document.querySelectorAll('.filter-button').forEach(item => item.setAttribute('aria-pressed', String(item === button)));
      document.querySelectorAll('.visual-card').forEach(card => { card.hidden = button.dataset.filter !== 'all' && card.dataset.category !== button.dataset.filter; });
    }));
  </script>
</body>
</html>
